@router.get("/auth/magic-link/inspect")
async def inspect_magic_link_details(
    token: str = Query(...),
    db: AsyncSession = Depends(get_db)
):
    stmt = select(MagicInvitation).where(
        MagicInvitation.token == token,
        MagicInvitation.expires_at > datetime.utcnow()
    )
    invitation = await db.scalar(stmt)
    if not invitation:
        raise HTTPException(status_code=404, detail="Token not recognized")

    email_parts = invitation.target_email.split("@")
    masked_email = f"{email_parts[0][:2]}***@{email_parts[1]}"

    return {
        "destination_email": masked_email,
        "organization_slug": invitation.organization_slug,
        "inviter_name": invitation.created_by_name
    }
